#include <stdint.h>
#include <ctype.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>

static int read_values(int values[], const int minimum[], const int maximum[], size_t count)
{
    char line[64];
    size_t length = 0;
    int ch;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (ch == 0 || length == sizeof line - 1) {
            return 0;
        }
        line[length++] = (char)ch;
    }
    if (ferror(stdin)) {
        return 0;
    }
    line[length] = '\0';

    char *cursor = line;
    for (size_t i = 0; i < count; ++i) {
        char *end;
        errno = 0;
        long value = strtol(cursor, &end, 10);
        if (end == cursor || errno == ERANGE || value < minimum[i] || value > maximum[i]) {
            return 0;
        }
        if (i + 1 < count && !isspace((unsigned char)*end)) {
            return 0;
        }
        values[i] = (int)value;
        cursor = end;
    }
    while (isspace((unsigned char)*cursor)) {
        ++cursor;
    }
    return *cursor == '\0';
}

static int *allocate_values(size_t count, int allowed)
{
    if (!allowed || count == 0 || count > SIZE_MAX / sizeof(int)) {
        return NULL;
    }
    /* TODO: make a positive, checked allocation. */
    return NULL;
}

int main(void)
{
    int input[2];
    const int minimum[] = {1, 0};
    const int maximum[] = {16, 1};
    if (!read_values(input, minimum, maximum, 2)) {
        puts("invalid");
        return 0;
    }
    const size_t count = (size_t)input[0];
    int *values = allocate_values(count, input[1]);
    if (values == NULL) {
        puts("allocation-failed");
        return 0;
    }
    int sum = 0;
    for (size_t i = 0; i < count; ++i) {
        values[i] = (int)i + 1;
        sum += values[i];
    }
    printf("sum %d\n", sum);
    free(values);
    return 0;
}

