{
    char line[64];
    size_t length = 0;
    int ch;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (ch == 0 || length == sizeof line - 1) {
            return 0;
        }
        line[length++] = (char)ch;
    }
    if (ferror(stdin)) {
        return 0;
    }
    line[length] = '\0';

    char *cursor = line;
    for (size_t i = 0; i < count; ++i) {
